export function isAppError(value: unknown): value is AppError {
	return (
		typeof value === 'object' && value !== null && 'message' in value && 'code' in value
	);
}

/** Turns anything thrown by a command into a user-facing error. */
export function toAppError(value: unknown): AppError {
	if (isAppError(value)) return value;
	void logError(String(value instanceof Error ? (value.stack ?? value.message) : value));
	return {
		message: 'Something went wrong.',
		suggestion: 'Try again. If it keeps happening, the app log has details.',
		code: 'general'
	};
}

