/** Sends `payload` to the window `label` (a presentation and its audience screen). */
export const sendToWindow = <T>(label: string, event: string, payload: T) => emitTo(label, event, payload);

/** What another window sends this one as `event`. */
export const onWindowMessage = <T>(event: string, handler: (payload: T) => void): Promise<UnlistenFn> =>
	listen<T>(event, (e) => handler(e.payload));
