/** Opens Lectrix's source code page or its author's profile in the default browser. */
export const openWebPage = (page: WebPage) => invoke<void>('open_web_page', { page });
/** The window buttons the title bar draws, and at which end (section 8). */
export const getWindowChrome = () => invoke<WindowChrome>('window_chrome');
/** This window's menus, for the system's menu bar (macOS). */
export const setMenu = (menus: MenuEntry[]) => invoke<void>('set_menu', { menus });

/** Listens to events for this window. (The plain `listen` of the event API would also
 * hear the ones Rust sends to Lectrix's other windows.) */
function listen<T>(event: string, handler: EventCallback<T>): Promise<UnlistenFn> {
	return getCurrentWebviewWindow().listen<T>(event, handler);
}

/** Files opened in this window by drag-and-drop or by launching Lectrix again with a file. */
export const onDocumentsOpened = (handler: (results: OpenResult[]) => void): Promise<UnlistenFn> =>
	listen<OpenResult[]>('documents-opened', (e) => handler(e.payload));

/** Tabs were moved into this window from another: `listOpenDocuments` has them. */
export const onDocumentsMoved = (handler: () => void): Promise<UnlistenFn> =>
	listen<null>('documents-moved', () => handler());

/** This window was asked to close and stays open (the user cancelled at its prompt about
 * unsaved changes): told to every window, for one that is waiting to quit Lectrix. */
export const closeDeclined = () => emit('close-declined');
export const onCloseDeclined = (handler: () => void): Promise<UnlistenFn> =>
	listen<null>('close-declined', () => handler());

/** This window read the recent files again, after something that may have changed them
 * (a file opened, saved under a new name, taken off the list): told to the other windows,
 * so their lists follow. */
export const recentChanged = () => emit('recent-changed', getCurrentWebviewWindow().label);
export const onRecentChanged = (handler: () => void): Promise<UnlistenFn> =>
	listen<string>('recent-changed', (e) => {
		if (e.payload !== getCurrentWebviewWindow().label) handler();
	});

/** A file opened in another window is open in a tab here: show it. */
export const onShowDocument = (handler: (id: number) => void): Promise<UnlistenFn> =>
	listen<number>('show-document', (e) => handler(e.payload));

/** A document of this window was saved from another (the Combine view's "Save and combine"). */
export const onDocumentSaved = (handler: (event: DocumentSaved) => void): Promise<UnlistenFn> =>
	listen<DocumentSaved>('document-saved', (e) => handler(e.payload));

/** The settings were changed in another window. */
export const onSettingsChanged = (handler: (settings: Settings) => void): Promise<UnlistenFn> =>
	listen<Settings>('settings-changed', (e) => handler(e.payload));

/** Files dropped on this window's Combine view, opened as sources. */
export const onMergeSourcesAdded = (handler: (results: OpenResult[]) => void): Promise<UnlistenFn> =>
	listen<OpenResult[]>('merge-sources-added', (e) => handler(e.payload));

/** An open document's file was changed or removed by another program (every window hears
 * of it; the one that shows the document acts). */
export const onFileChanged = (handler: (event: FileChangedEvent) => void): Promise<UnlistenFn> =>
	listen<FileChangedEvent>('file-changed', (e) => handler(e.payload));

/** A touchpad pinch the webview would have applied to the whole app (Linux). */
export const onTouchpadPinch = (handler: (event: TouchpadPinch) => void): Promise<UnlistenFn> =>
	listen<TouchpadPinch>('touchpad-pinch', (e) => handler(e.payload));

/** An item of this window's menus was chosen in the system's menu bar (macOS): its id. */
export const onMenuCommand = (handler: (id: string) => void): Promise<UnlistenFn> =>
	listen<string>('menu-command', (e) => handler(e.payload));

export interface TileRect {
	x: number;
	y: number;
	width: number;
	height: number;
}

/** The format page images are requested in (set once from StartupInfo). */
let imageFormat: ImageFormat = 'png';

export function setImageFormat(format: ImageFormat) {
	imageFormat = format;
}

/** The image format pages are fetched in. */
export function imageFormatInUse(): ImageFormat {
	return imageFormat;
}

/** Part of a page an image can show: without its annotations, or its annotations alone
 * (for an inverted page, `annots-dark`); or the page as it prints, with or without its
 * annotations (`print`, `print-content`: the Print dialog's preview). */
export type PageLayer = 'content' | 'annots' | 'annots-dark' | 'print' | 'print-content';

/** The most annotations a page image can be asked to leave out (mirrors `MAX_HIDDEN` in
 * `protocol.rs`); with more, the page is asked for with all of them. */
export const MAX_HIDDEN = 1024;

/**
 * URL of a rendered page image. WebView2 (Windows) serves custom protocols as
 * http://<scheme>.localhost; other platforms use <scheme>://localhost. `hidden` names the
 * annotations to leave out, by object number: the ones the annotation list filters out.
 * `layer` asks for part of the page: its content without annotations, or its annotations
 * alone (`protocol.rs`; section 6.1, visual adjustments).
 */
export function pageUrl(
	docId: number,
	pageIndex: number,
	scale: number,
	rev: number,
	tile?: TileRect,
	format: ImageFormat = imageFormat,
	hidden: readonly number[] = [],
	layer?: PageLayer
): string {
	const base = isWindows() ? 'http://lectrix.localhost' : 'lectrix://localhost';
	let url = `${base}/page/${docId}/${pageIndex}?scale=${scale.toFixed(3)}&rev=${rev}`;
	if (tile) url += `&tile=${tile.x},${tile.y},${tile.width},${tile.height}`;
	// The content has no annotations to leave out, and printing leaves out none.
	const hides = layer !== 'content' && layer !== 'print' && layer !== 'print-content';
	if (hides && hidden.length > 0 && hidden.length <= MAX_HIDDEN) url += `&hide=${hidden.join(',')}`;
	if (layer) url += `&layer=${layer}`;
	if (format === 'png') url += '&fmt=png';
	return url;
}

/** URL of page `page` (0-based) of a file Compress is working on, as it was or (`after`)
 * as compressing made it, at `scale`. */
export function compressPreviewUrl(token: number, after: boolean, page: number, scale: number): string {
	const base = isWindows() ? 'http://lectrix.localhost' : 'lectrix://localhost';
	return `${base}/compress/${token}/${after ? 'after' : 'before'}/${page}?scale=${scale.toFixed(3)}`;
}

/**
 * URL of a preview of a recent file's first page, `width` device pixels wide. `openedAt`
 * is the entry's, so the URL fails rather than shows another file once the list changes.
 */
export function recentPreviewUrl(index: number, openedAt: number, width: number): string {
	const base = isWindows() ? 'http://lectrix.localhost' : 'lectrix://localhost';
	return `${base}/recent/${index}?w=${Math.round(width)}&opened=${openedAt}`;
}

function isWindows(): boolean {
	return typeof navigator !== 'undefined' && /Windows/i.test(navigator.userAgent);
}

/** A fetched page image, ready to draw once into a canvas. */
export interface PageImage {
	width: number;
	height: number;
	/** Draws the image at the canvas origin, once; then its pixels are released. */
	draw(ctx: CanvasRenderingContext2D): void;
}

/** Fetches a page or tile (raw RGBA or PNG, by the response type). */
export async function fetchPageImage(url: string, signal?: AbortSignal): Promise<PageImage> {
	const response = await fetch(url, { signal });
	if (!response.ok) throw new Error(`${response.status} ${await response.text()}`);
	if (response.headers.get('Content-Type') === 'image/png') {
		let bitmap: ImageBitmap | null = await createImageBitmap(await response.blob());
		const { width, height } = bitmap;
		return {
			width,
			height,
			draw: (ctx) => {
				if (!bitmap) return;
				ctx.drawImage(bitmap, 0, 0);
				bitmap.close();
				bitmap = null;
			}
		};
	}
	const width = Number(response.headers.get('X-Lectrix-Width'));
	const height = Number(response.headers.get('X-Lectrix-Height'));
	const buffer = await response.arrayBuffer();
	if (!width || !height || buffer.byteLength !== width * height * 4) {
		throw new Error(`unexpected image size ${width}x${height} (${buffer.byteLength} bytes)`);
	}
	// Dropped after drawing: the request's promise outlives the draw, and must not keep
	// megabytes of pixels alive next to the canvas that already holds them.
	let pixels: ImageData | null = new ImageData(new Uint8ClampedArray(buffer), width, height);
	return {
		width,
		height,
		draw: (ctx) => {
			if (pixels) ctx.putImageData(pixels, 0, 0);
			pixels = null;
		}
	};
}

/**
 * Has Rust render the page image at `url` and keep it, without sending it (`warm=1`): a
 * page rendered ahead, which is then there when it is shown.
 */
export async function warmPageImage(url: string): Promise<void> {
	const response = await fetch(`${url}&warm=1`);
	if (!response.ok) throw new Error(`${response.status} ${await response.text()}`);
}
